53	  url: string,
54	  timeout: number,
55	  options?: RequestInit,
56	): Promise<Response> {
57	  const controller = new AbortController();
58	  const timeoutId = setTimeout(() => controller.abort(), timeout);
59	
60	  if (options?.signal) {
61	    if (options.signal.aborted) {
62	      controller.abort();
