import { getErrorMessage, isNodeError } from './errors.js';
import { URL } from 'node:url';
import * as dns from 'node:dns';
import * as net from 'node:net';
import { Agent, ProxyAgent, setGlobalDispatcher } from 'undici';

const DEFAULT_HEADERS_TIMEOUT = 300000; // 5 minutes
const DEFAULT_BODY_TIMEOUT = 300000; // 5 minutes

export class FetchError extends Error {
  constructor(
    message: string,
    public code?: string,
    options?: ErrorOptions,
  ) {
    super(message, options);
    this.name = 'FetchError';
  }
}

/**
 * Error thrown when an attempt is made to access a private, reserved, or
 * otherwise non-routable network address.
 */
export class PrivateIpError extends Error {
  constructor(message = 'Access to private network is blocked') {
    super(message);
    this.name = 'PrivateIpError';
  }
}

// -----------------------------------------------------------------------------
// IP address parsing helpers
// -----------------------------------------------------------------------------

/**
 * Converts a dotted-quad IPv4 string into a 32-bit unsigned integer. Returns
 * null if the string is not a valid IPv4 address.
 */
function ipv4ToInt(address: string): number | null {
  if (!net.isIPv4(address)) {
    return null;
  }
  const parts = address.split('.');
